// Hover Taxi - trip planner (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var spd=[120,600,2400], rng=[150,2000,20000];
var trips=[["downtown commute",25],["intercity",400],["continental",4000]];
console.log("Hover Taxi - trip times by generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": "+spd[m]+" km/h, "+rng[m]+" km range");
  for(var t=0;t<trips.length;t++){ var mins=trips[t][1]/spd[m]*60; console.log("  "+trips[t][0]+" ("+trips[t][1]+" km): "+(mins<60?mins.toFixed(0)+" min":(mins/60).toFixed(1)+" h")); }
}

